          text-align: center;
          white-space: nowrap;
          overflow: hidden;
          text-overflow: ellipsis;
        }
        .team-name.away {
          text-align: right;
          padding-right: 10rpx;
        }
        .team-name.home {
          text-align: left;
          padding-left: 10rpx;
        }
        .vs-text {
          width: 40rpx;
          text-align: center;
          flex-shrink: 0;
          font-weight: 500;
        }
      }

      // 胜率行：样式统一
      .rate-row {
        width: 100%;
        display: flex;
        align-items: center;
        font-size: 22rpx;
        color: #999;

        .rate-text {
          flex: 1;
          text-align: center;
          white-space: nowrap;
          overflow: hidden;
          text-overflow: ellipsis;
        }
        .rate-text.away {
          text-align: right;
          padding-right: 10rpx;
        }
        .rate-text.home {
          text-align: left;
          padding-left: 10rpx;
        }
        .vs-text {
          width: 40rpx;
          text-align: center;
          flex-shrink: 0;
        }
      }

      // 大小分赔率按钮行：替换原有selected-content，样式对齐
      .odds-row {
        width: 100%;
        display: flex;
        gap: 2rpx;
        margin-top: 4rpx;

        .match-cell {
          flex: 1;
          text-align: center;
          padding: 12rpx 0;
          background-color: #f0f0f0;
          color: #333;
          font-size: 24rpx;
          border-radius: 4rpx;
          
          &.selected {
            background-color: #d92929;
            color: #fff;
          }
          
          &:active {
            background: #e5e5e5;
          }
          
          &.selected:active {
            background: #c62828;
          }
        }
      }
    }
  }
}

/* 底部投注栏：统一对齐让分胜负页样式 */
.bet-bar {
  position: fixed !important;
  width: 100% !important;
  left: 0 !important;
  z-index: 10 !important;
  background-color: #fff;
  box-shadow: 0 -2rpx 10rpx rgba(0,0,0,0.1);
  padding-bottom: 0 !important;
